const tierOf = pop => pop>=200 ? 'mega' : pop>=50 ? 'large' : pop>=10 ? 'mid' : pop>=1 ? 'small' : 'micro';

function tauntFor(c, avoid){
  if(LANG==='en') return pick(TAUNTS[c.code], avoid);
  const bank=GTAUNT[LANG];
  if(!bank) return pick(TAUNTS[c.code], avoid);
  const line=pick(bank[tierOf(c.pop)], null);
  return line.split('{n}').join(cname(c));
}
const passLine = avoid => LANG==='en' ? pick(PASS_LINES, avoid)
  : pick((GTAUNT[LANG]||{}).pass || PASS_LINES, avoid);
const winLine = avoid => LANG==='en' ? pick(WIN_LINES, avoid)
  : pick((GTAUNT[LANG]||{}).win || WIN_LINES, avoid);


